228	        if (actual[roleKey] !== roleExpected) {
229	          issues.push(`[agents.${key}].${roleKey} must be ${JSON.stringify(roleExpected)}`);
230	        }
231	      }
232	      continue;
233	    }
234	    if (actual !== expected) {
