 90	async function readOptional(filePath: string): Promise<string | null> {
 91	  try {
 92	    return await readFile(filePath, "utf8");
 93	  } catch (error) {
 94	    if (isRecord(error) && error.code === "ENOENT") return null;
 95	    throw error;
 96	  }
 97	}
